SELECT id,task_num,type,task_detail,task_address,site_route,principal,end_time,create_time,status,deal_method,evaluate,deal_result
FROM tb_task


   AND task_num like concat('%', #{taskDto.taskNum}, '%')


   AND status = #{taskDto.status}


   AND type = #{taskDto.type}


   AND principal = #{taskDto.principal}


   AND end_time <= #{taskDto.endTime}


   AND end_time >= #{taskDto.endStartTime}

