mapper.update:
UPDATE tb_task

     deal_method = #{taskDto.dealMethod},
     deal_result = #{taskDto.dealResult},
     status = #{taskDto.status},
     finish_time = #{taskDto.finishTime}

WHERE id = #{taskDto.id}

UPDATE tb_task

  evaluate = #{taskDto.evaluate},
  evaluate_user = #{taskDto.evaluateUser},
  evaluate_time = #{taskDto.evaluateTime}

WHERE id = #{taskDto.id}

