mapper.select:
SELECT node_id as nodeId,node_type as nodeType
FROM tb_node
WHERE site_route = #{siteRoute}

SELECT count(1) as sum,DATE_FORMAT( create_time, '%Y-%m-%d' ) AS day
FROM tb_task
WHERE DATE_FORMAT( create_time, '%Y-%m-%d' ) in

 #{day}


  AND type = #{taskDto.type}


  AND site_route like concat(#{taskDto.taskSiteRoute}, '%')


  AND principal = #{taskDto.principal}

GROUP BY day
ORDER BY day

